     1→/**
     2→ * OAuth Handler - Social Login Routes
     3→ */
     4→
     5→import { Request, Response } from 'express';
     6→import axios from 'axios';
     7→import jwt from 'jsonwebtoken';
     8→
     9→export interface OAuthUser {
    10→  id: string;
    11→  email: string;
    12→  name: string;
    13→  avatar?: string;
    14→  provider: string;
    15→}
    16→
    17→export class OAuthHandler {
    18→  private jwtSecret = process.env.JWT_SECRET || 'your-secret-key';
    19→
    20→  /**
    21→   * Google OAuth Callback
    22→   */
    23→  async handleGoogleCallback(
    24→    code: string,
    25→    redirectUri: string
    26→  ): Promise<OAuthUser> {
    27→    const tokenResponse = await axios.post(
    28→      'https://oauth2.googleapis.com/token',
    29→      {
    30→        code,
    31→        client_id: process.env.GOOGLE_CLIENT_ID,
    32→        client_secret: process.env.GOOGLE_CLIENT_SECRET,
    33→        redirect_uri: redirectUri,
    34→        grant_type: 'authorization_code',
    35→      }
    36→    );
    37→
    38→    const accessToken = tokenResponse.data.access_token;
    39→
    40→    const userResponse = await axios.get(
    41→      'https://www.googleapis.com/oauth2/v2/userinfo',
    42→      {
    43→        headers: { Authorization: `Bearer ${accessToken}` },
    44→      }
    45→    );
    46→
    47→    return {
    48→      id: userResponse.data.id,
    49→      email: userResponse.data.email,
    50→      name: userResponse.data.name,
    51→      avatar: userResponse.data.picture,
    52→      provider: 'google',
    53→    };
    54→  }
    55→
    56→  /**
    57→   * GitHub OAuth Callback
    58→   */
    59→  async handleGithubCallback(
    60→    code: string,
    61→    redirectUri: string
    62→  ): Promise<OAuthUser> {
    63→    const tokenResponse = await axios.post(
    64→      'https://github.com/login/oauth/access_token',
    65→      {
    66→        client_id: process.env.GITHUB_CLIENT_ID,
    67→        client_secret: process.env.GITHUB_CLIENT_SECRET,
    68→        code,
    69→        redirect_uri: redirectUri,
    70→      },
    71→      {
    72→        headers: { Accept: 'application/json' },
    73→      }
    74→    );
    75→
    76→    const accessToken = tokenResponse.data.access_token;
    77→
    78→    const userResponse = await axios.get('https://api.github.com/user', {
    79→      headers: { Authorization: `Bearer ${accessToken}` },
    80→    });
    81→
    82→    return {
    83→      id: userResponse.data.id.toString(),
    84→      email: userResponse.data.email,
    85→      name: userResponse.data.name || userResponse.data.login,
    86→      avatar: userResponse.data.avatar_url,
    87→      provider: 'github',
    88→    };
    89→  }
    90→
    91→  /**
    92→   * Naver OAuth Callback
    93→   */
    94→  async handleNaverCallback(code: string, state: string): Promise<OAuthUser> {
    95→    const tokenResponse = await axios.post(
    96→      'https://nid.naver.com/oauth2.0/token',
    97→      null,
    98→      {
    99→        params: {
   100→          grant_type: 'authorization_code',
   101→          client_id: process.env.NAVER_CLIENT_ID,
   102→          client_secret: process.env.NAVER_CLIENT_SECRET,
   103→          code,
   104→          state,
   105→        },
   106→      }
   107→    );
   108→
   109→    const accessToken = tokenResponse.data.access_token;
   110→
   111→    const userResponse = await axios.get('https://openapi.naver.com/v1/nid/me', {
   112→      headers: { Authorization: `Bearer ${accessToken}` },
   113→    });
   114→
   115→    const response = userResponse.data.response;
   116→
   117→    return {
   118→      id: response.id,
   119→      email: response.email,
   120→      name: response.name,
   121→      avatar: response.profile_image,
   122→      provider: 'naver',
   123→    };
   124→  }
   125→
   126→  /**
   127→   * Generate JWT Token
   128→   */
   129→  generateToken(user: OAuthUser): string {
   130→    const token = jwt.sign(
   131→      {
   132→        id: user.id,
   133→        email: user.email,
   134→        name: user.name,
   135→        provider: user.provider,
   136→      },
   137→      this.jwtSecret,
   138→      { expiresIn: '7d' }
   139→    );
   140→
   141→    return token;
   142→  }
   143→
   144→  /**
   145→   * Verify JWT Token
   146→   */
   147→  verifyToken(token: string): any {
   148→    try {
   149→      return jwt.verify(token, this.jwtSecret);
   150→    } catch (error) {
   151→      return null;
   152→    }
   153→  }
   154→}
   155→
   156→export const oauthHandler = new OAuthHandler();
   157→

