    53→  const clientID = config.github.clientID;
    54→  const redirectUri = encodeURIComponent(config.github.callbackURL);
    55→  const scope = encodeURIComponent('user:email');
    56→
    57→  const authUrl = `https://github.com/login/oauth/authorize?client_id=${clientID}&redirect_uri=${redirectUri}&scope=${scope}`;
    58→
    59→  res.redirect(authUrl);
    60→});
    61→
    62→router.get('/github/callback', async (req: Request, res: Response) => {
    63→  try {
    64→    const { code } = req.query;
    65→
    66→    if (!code) {
    67→      return res.status(400).json({ error: 'Missing authorization code' });
    68→    }
    69→
    70→    const user = await oauthHandler.handleGithubCallback(
    71→      code as string,
    72→      config.github.callbackURL
    73→    );
    74→    const token = oauthHandler.generateToken(user);
    75→
    76→    res.redirect(`https://253.dclub.kr?token=${token}&user=${encodeURIComponent(JSON.stringify(user))}`);
    77→  } catch (error) {
    78→    res.status(500).json({ error: 'GitHub OAuth failed' });
    79→  }
    80→});
    81→
    82→/**
    83→ * Naver OAuth Routes
    84→ */
    85→router.get('/naver', (req: Request, res: Response) => {
    86→  const clientID = config.naver.clientID;
    87→  const redirectUri = encodeURIComponent(config.naver.callbackURL);
    88→  const state = Math.random().toString(36).substring(7);
    89→
    90→  req.session!.naverState = state;
    91→
    92→  const authUrl = `https://nid.naver.com/oauth2.0/authorize?client_id=${clientID}&response_type=code&redirect_uri=${redirectUri}&state=${state}`;
    93→
    94→  res.redirect(authUrl);
    95→});
    96→
    97→router.get('/naver/callback', async (req: Request, res: Response) => {
    98→  try {
    99→    const { code, state } = req.query;
   100→
   101→    if (!code) {
   102→      return res.status(400).json({ error: 'Missing authorization code' });
   103→    }
   104→
   105→    if (state !== req.session!.naverState) {
   106→      return res.status(400).json({ error: 'State mismatch' });
   107→    }
   108→
   109→    const user = await oauthHandler.handleNaverCallback(
   110→      code as string,
   111→      state as string
   112→    );
   113→    const token = oauthHandler.generateToken(user);
   114→
   115→    res.redirect(`https://253.dclub.kr?token=${token}&user=${encodeURIComponent(JSON.stringify(user))}`);
   116→  } catch (error) {
   117→    res.status(500).json({ error: 'Naver OAuth failed' });
   118→  }
   119→});
   120→
   121→/**
   122→ * Verify Token Endpoint
   123→ */
   124→router.get('/verify', (req: Request, res: Response) => {
   125→  const token = req.headers.authorization?.split(' ')[1];
   126→
   127→  if (!token) {
   128→    return res.status(401).json({ error: 'Missing token' });
   129→  }
   130→
   131→  const user = oauthHandler.verifyToken(token);
   132→
   133→  if (!user) {
   134→    return res.status(401).json({ error: 'Invalid token' });
   135→  }
   136→
   137→  res.json({ valid: true, user });
   138→});
   139→
   140→/**
   141→ * Logout Endpoint
   142→ */
   143→router.post('/logout', (req: Request, res: Response) => {
   144→  req.session?.destroy((err) => {
   145→    if (err) {
   146→      return res.status(500).json({ error: 'Logout failed' });
   147→    }
   148→
   149→    res.json({ message: 'Logged out successfully' });
   150→  });
   151→});
   152→
   153→export default router;
