    14→  google: OAuthProvider;
    15→  github: OAuthProvider;
    16→  naver: OAuthProvider;
    17→}
    18→
    19→export const loadOAuthConfig = (): OAuthConfig => {
    20→  const baseURL = process.env.BASE_URL || 'https://253.dclub.kr';
    21→
    22→  return {
    23→    google: {
    24→      name: 'google',
    25→      clientID: process.env.GOOGLE_CLIENT_ID || '',
    26→      clientSecret: process.env.GOOGLE_CLIENT_SECRET || '',
    27→      callbackURL: `${baseURL}/auth/google/callback`,
    28→    },
    29→    github: {
    30→      name: 'github',
    31→      clientID: process.env.GITHUB_CLIENT_ID || '',
    32→      clientSecret: process.env.GITHUB_CLIENT_SECRET || '',
    33→      callbackURL: `${baseURL}/auth/github/callback`,
    34→    },
    35→    naver: {
    36→      name: 'naver',
    37→      clientID: process.env.NAVER_CLIENT_ID || '',
    38→      clientSecret: process.env.NAVER_CLIENT_SECRET || '',
    39→      callbackURL: `${baseURL}/auth/naver/callback`,
    40→    },
    41→  };
    42→};
