    44→export const validateOAuthConfig = (config: OAuthConfig): void => {
    45→  const missingProviders = [];
    46→
    47→  if (!config.google.clientID) missingProviders.push('Google');
    48→  if (!config.github.clientID) missingProviders.push('GitHub');
