    11→const app: Express = express();
    12→const PORT = process.env.SERVER_PORT || 3001;
    13→
    14→// ============================================================================
    15→// Middleware
    16→// ============================================================================
    17→
    18→// CORS
    19→app.use(
    20→  cors({
    21→    origin: process.env.FRONTEND_URL || 'https://253.dclub.kr',
    22→    credentials: true,
    23→  })
    24→);
    25→
    26→// Body Parser
    27→app.use(express.json());
    28→app.use(express.urlencoded({ extended: true }));
    29→
    30→// Session
    31→app.use(
    32→  session({
    33→    secret: process.env.SESSION_SECRET || 'your-session-secret',
    34→    resave: false,
    35→    saveUninitialized: false,
    36→    cookie: {
    37→      secure: process.env.NODE_ENV === 'production',
    38→      httpOnly: true,
    39→      maxAge: 1000 * 60 * 60 * 24 * 7, // 7 days
    40→    },
    41→  })
    42→);
    43→
    44→// ============================================================================
    45→// Authentication Middleware
    46→// ============================================================================
    47→
    48→export const authMiddleware = (
    49→  req: Request,
    50→  res: Response,
    51→  next: NextFunction
    52→) => {
    53→  const token = req.headers.authorization?.split(' ')[1];
    54→
    55→  if (!token) {
    56→    return res.status(401).json({ error: 'Missing authentication token' });
    57→  }
    58→
    59→  const user = oauthHandler.verifyToken(token);
    60→
    61→  if (!user) {
    62→    return res.status(401).json({ error: 'Invalid or expired token' });
    63→  }
    64→
    65→  (req as any).user = user;
    66→  next();
    67→};
